                        .requestMatchers("/api/auth/**").permitAll()
                        .anyRequest().authenticated())
                .exceptionHandling(exceptions -> exceptions
                        .authenticationEntryPoint((request, response, exception) -> {
                            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                            response.setCharacterEncoding(StandardCharsets.UTF_8.name());
                            response.setContentType("application/json;charset=UTF-8");
                            response.getWriter().write(
                                    "{\"code\":401,\"message\":\"未认证\",\"data\":null}");
                        }))
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public AuthenticationManager authenticationManager(
            AuthenticationConfiguration authenticationConfiguration) throws Exception {
        return authenticationConfiguration.getAuthenticationManager();
    }
}

package com.esf.service.service;

import com.esf.service.dto.LoginRequest;
import com.esf.service.dto.LoginResponse;
import com.esf.service.entity.User;
import com.esf.service.mapper.UserMapper;
import com.esf.service.security.JwtUtil;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

@Service
public class AuthService {
    private final UserMapper userMapper;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtil jwtUtil;

    public AuthService(UserMapper userMapper, PasswordEncoder passwordEncoder, JwtUtil jwtUtil) {
        this.userMapper = userMapper;
        this.passwordEncoder = passwordEncoder;
        this.jwtUtil = jwtUtil;
    }

    public LoginResponse login(LoginRequest request) {
        if (request == null || request.getUsername() == null || request.getPassword() == null) {
            return null;
        }
        User user = userMapper.findByUsername(request.getUsername());
        if (user == null || !passwordEncoder.matches(request.getPassword(), user.getPassword())) {
            return null;
        }
        return new LoginResponse(
                jwtUtil.generateToken(user.getUsername(), user.getRole()),
                user.getUsername(), user.getRole());
    }
}

package com.esf.service.service;

import com.esf.service.entity.Department;
import com.esf.service.mapper.DepartmentMapper;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.stereotype.Service;

@Service
public class DepartmentService {
    private final DepartmentMapper departmentMapper;

    public DepartmentService(DepartmentMapper departmentMapper) {
        this.departmentMapper = departmentMapper;
    }

    public Department create(String name, String orgId) {
        Department department = new Department();
        department.setName(name);
        department.setOrgId(orgId);
        department.setCreatedAt(LocalDateTime.now());
        departmentMapper.insert(department);
        return department;
    }

    public List<Department> list(String orgId) {
        return orgId != null && !orgId.isEmpty()
                ? departmentMapper.findByOrgId(orgId)
                : departmentMapper.findAll();
    }
}

package com.esf.service.service;

import com.esf.service.dto.PageResult;
import com.esf.service.dto.ServiceOrderRequest;
import com.esf.service.dto.ServiceQueryParams;
import com.esf.service.entity.ServiceOrder;
import com.esf.service.mapper.ServiceOrderMapper;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.stereotype.Service;

@Service
public class ServiceOrderService {
    private static final DateTimeFormatter SERVICE_ID_TIME =
            DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
    private final AtomicInteger sequence = new AtomicInteger(1);
    private final ServiceOrderMapper serviceOrderMapper;

    public ServiceOrderService(ServiceOrderMapper serviceOrderMapper) {
        this.serviceOrderMapper = serviceOrderMapper;
    }

    public ServiceOrder createOrder(ServiceOrderRequest request) {
        LocalDateTime now = LocalDateTime.now();
        ServiceOrder order = new ServiceOrder();
        order.setServiceId("P" + now.format(SERVICE_ID_TIME)
                + String.format("%06d", sequence.getAndIncrement()));
        order.setCustomerName(request.getCustomerName());
        order.setOwner(null);
        order.setStatus("PENDING");
        order.setBizType(defaultIfNull(request.getBizType(), "CONSULT"));
        order.setPriority(defaultIfNull(request.getPriority(), "P2"));
        order.setSourceChannel(defaultIfNull(request.getSourceChannel(), "WEB"));
        order.setRegion(defaultIfNull(request.getRegion(), "EAST"));
        order.setProductLine(request.getProductLine());
        order.setContactName(request.getContactName());
        order.setSlaLevel(request.getSlaLevel());
        order.setOrgId(request.getOrgId());
        order.setDepartmentId(request.getDepartmentId());
        order.setSkillGroupId(request.getSkillGroupId());
        order.setDescription(request.getDescription());
        order.setCreatedAt(now);
        order.setUpdatedAt(now);
        serviceOrderMapper.insert(order);
        return order;
    }

    public ServiceOrder getOrderById(Long id) {
        return serviceOrderMapper.findById(id);
    }

    public PageResult<ServiceOrder> queryOrders(ServiceQueryParams params) {
        int current = params.getCurrent() == null ? 1 : params.getCurrent();
        int size = params.getSize() == null ? 10 : params.getSize();
        int offset = (current - 1) * size;
        List<ServiceOrder> records = serviceOrderMapper.queryList(
                params.getType(), params.getTypeValue(), params.getOrgId(),
                params.getDepartmentId(), params.getSkillGroupId(), params.getStatus(),
                offset, size);
        long total = serviceOrderMapper.queryCount(
                params.getType(), params.getTypeValue(), params.getOrgId(),
                params.getDepartmentId(), params.getSkillGroupId(), params.getStatus());
        return new PageResult<>(records, total, current, size);
    }

    public Map<String, Object> updateStatus(Long id, String status, String owner) {
        int updated = serviceOrderMapper.updateStatus(id, status, owner, LocalDateTime.now());
        if (updated == 0) {
            return null;
        }
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("id", id);
        result.put("status", status);
        result.put("owner", owner);
        return result;
    }

    public Map<String, Long> getStats(String orgId) {
        boolean scoped = orgId != null && !orgId.isEmpty();
        Map<String, Long> stats = new LinkedHashMap<>();
        stats.put("total", scoped ? serviceOrderMapper.countByOrgId(orgId) : serviceOrderMapper.count());
        stats.put("pending", countStatus(scoped, orgId, "PENDING"));
        stats.put("inProgress", countStatus(scoped, orgId, "IN_PROGRESS"));
        stats.put("completed", countStatus(scoped, orgId, "COMPLETED"));
        stats.put("cancelled", countStatus(scoped, orgId, "CANCELLED"));
        return stats;
    }

    private long countStatus(boolean scoped, String orgId, String status) {
        return scoped
                ? serviceOrderMapper.countByOrgIdAndStatus(orgId, status)
                : serviceOrderMapper.countByStatus(status);
    }

    private String defaultIfNull(String value, String defaultValue) {
        return value == null ? defaultValue : value;
    }
}
